export function getExportSafetyNotice() {
    return 'AI Export does not call an AI service. It formats captured debug context locally. Exported data may contain cookies, authorization headers, tokens, request/response bodies, personal information, or other sensitive data. Review it before sharing. 外部送信は行いません。共有前にCookie、Authorization、token、個人情報などの機密情報を確認してください。';
}
